/* CommerceForge Dev Docs — Global Styles */

:root {
  --bg-primary: #0d1117;
  --bg-secondary: #161b22;
  --bg-tertiary: #1c2128;
  --bg-card: rgba(22, 27, 34, 0.7);
  --border-color: rgba(71, 95, 145, 0.25);
  --border-hover: rgba(71, 95, 145, 0.5);
  --accent: #475F91;
  --accent-light: #6b8cce;
  --accent-green: #3fb950;
  --accent-cyan: #39c5cf;
  --text-primary: #ffffff;
  --text-secondary: #b0b8c4;
  --text-muted: #6e7681;
  --code-bg: #0d1117;
  --code-border: #30363d;
  --radius: 12px;
  --radius-sm: 8px;
  --shadow: 0 4px 24px rgba(0, 0, 0, 0.4);
  --shadow-lg: 0 8px 32px rgba(0, 0, 0, 0.5);
  --transition: 0.2s ease;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: 'Inter', system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

a {
  color: var(--accent-light);
  text-decoration: none;
  transition: color var(--transition);
}

a:hover {
  color: var(--text-primary);
}

/* Typography */
h1, h2, h3, h4 {
  font-weight: 600;
  line-height: 1.2;
  letter-spacing: -0.02em;
}

h1 { font-size: 2.75rem; }
h2 { font-size: 2rem; }
h3 { font-size: 1.25rem; }
h4 { font-size: 1rem; }

p {
  color: var(--text-secondary);
}

/* Layout */
.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
}

.section {
  padding: 80px 0;
}

.section-title {
  font-size: 2rem;
  margin-bottom: 12px;
}

.section-subtitle {
  font-size: 1.125rem;
  color: var(--text-secondary);
  margin-bottom: 48px;
  max-width: 640px;
}

/* Header */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(13, 17, 23, 0.85);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border-color);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 64px;
}

.logo {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--text-primary);
  display: flex;
  align-items: center;
  gap: 10px;
}

.logo-mark {
  width: 28px;
  height: 28px;
  background: linear-gradient(135deg, var(--accent), var(--accent-cyan));
  border-radius: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.75rem;
  color: white;
}

.main-nav {
  display: flex;
  gap: 28px;
}

.main-nav a {
  color: var(--text-secondary);
  font-size: 0.9375rem;
  font-weight: 500;
  position: relative;
}

.main-nav a:hover,
.main-nav a.active {
  color: var(--text-primary);
}

.main-nav a.active::after {
  content: '';
  position: absolute;
  bottom: -20px;
  left: 0;
  right: 0;
  height: 2px;
  background: var(--accent-green);
}

.header-utils {
  display: flex;
  align-items: center;
  gap: 16px;
}

.search-btn,
.theme-btn {
  background: none;
  border: none;
  color: var(--text-secondary);
  cursor: pointer;
  padding: 6px;
  border-radius: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--transition);
}

.search-btn:hover,
.theme-btn:hover {
  color: var(--text-primary);
  background: var(--bg-tertiary);
}

.mobile-menu-btn {
  display: none;
  background: none;
  border: none;
  color: var(--text-secondary);
  cursor: pointer;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 10px 20px;
  border-radius: var(--radius-sm);
  font-size: 0.9375rem;
  font-weight: 500;
  cursor: pointer;
  transition: all var(--transition);
  border: none;
}

.btn-primary {
  background: var(--accent-green);
  color: #000;
}

.btn-primary:hover {
  background: #4dd163;
  color: #000;
}

.btn-secondary {
  background: var(--bg-tertiary);
  color: var(--text-primary);
  border: 1px solid var(--border-color);
}

.btn-secondary:hover {
  border-color: var(--border-hover);
  background: var(--bg-secondary);
}

.btn-ghost {
  background: transparent;
  color: var(--accent-light);
  padding: 0;
}

.btn-ghost:hover {
  color: var(--text-primary);
}

/* Cards */
.card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  padding: 28px;
  transition: all var(--transition);
  backdrop-filter: blur(8px);
}

.card:hover {
  border-color: var(--border-hover);
  transform: translateY(-2px);
  box-shadow: var(--shadow);
}

.card-icon {
  width: 40px;
  height: 40px;
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 16px;
  font-size: 1.25rem;
}

.card h3 {
  margin-bottom: 8px;
  color: var(--text-primary);
}

.card p {
  font-size: 0.9375rem;
  margin-bottom: 16px;
}

/* Code blocks */
.code-block {
  background: var(--code-bg);
  border: 1px solid var(--code-border);
  border-radius: var(--radius-sm);
  overflow: hidden;
  font-family: 'JetBrains Mono', 'Fira Code', monospace;
  font-size: 0.875rem;
}

.code-tabs {
  display: flex;
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--code-border);
}

.code-tab {
  padding: 8px 16px;
  font-size: 0.8125rem;
  color: var(--text-muted);
  cursor: pointer;
  border: none;
  background: none;
  font-family: inherit;
  transition: all var(--transition);
  border-bottom: 2px solid transparent;
  margin-bottom: -1px;
}

.code-tab:hover {
  color: var(--text-secondary);
}

.code-tab.active {
  color: var(--text-primary);
  border-bottom-color: var(--accent-green);
}

.code-content {
  padding: 16px;
  overflow-x: auto;
}

.code-content pre {
  margin: 0;
  color: var(--text-primary);
  line-height: 1.6;
}

.code-content .comment { color: var(--text-muted); }
.code-content .keyword { color: #ff7b72; }
.code-content .string { color: #a5d6ff; }

/* Accordions */
.accordion {
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  overflow: hidden;
  margin-bottom: 12px;
  background: var(--bg-card);
}

.accordion-header {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 18px 24px;
  background: none;
  border: none;
  color: var(--text-primary);
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  text-align: left;
  font-family: inherit;
  transition: background var(--transition);
}

.accordion-header:hover {
  background: rgba(71, 95, 145, 0.08);
}

.accordion-header .chevron {
  transition: transform var(--transition);
  color: var(--text-muted);
}

.accordion.open .accordion-header .chevron {
  transform: rotate(180deg);
}

.accordion-body {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease, padding 0.3s ease;
}

.accordion.open .accordion-body {
  max-height: 600px;
}

.accordion-inner {
  padding: 0 24px 24px;
}

.accordion-step {
  display: flex;
  gap: 16px;
  margin-bottom: 20px;
}

.step-num {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: var(--bg-tertiary);
  border: 1px solid var(--border-color);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--accent-light);
  flex-shrink: 0;
}

.step-content {
  flex: 1;
}

.step-content p {
  font-size: 0.9375rem;
  margin-bottom: 10px;
}

/* Footer */
.site-footer {
  border-top: 1px solid var(--border-color);
  background: var(--bg-secondary);
  padding: 60px 0 32px;
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 40px;
  margin-bottom: 48px;
}

.footer-col h4 {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--text-primary);
  margin-bottom: 16px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.footer-col ul {
  list-style: none;
}

.footer-col li {
  margin-bottom: 10px;
}

.footer-col a {
  color: var(--text-secondary);
  font-size: 0.9375rem;
}

.footer-col a:hover {
  color: var(--text-primary);
}

.footer-bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-top: 24px;
  border-top: 1px solid var(--border-color);
}

.footer-bottom p {
  font-size: 0.875rem;
  color: var(--text-muted);
}

/* Sidebar (docs pages) */
.docs-layout {
  display: flex;
  min-height: calc(100vh - 64px);
}

.sidebar {
  width: 280px;
  background: var(--bg-secondary);
  border-right: 1px solid var(--border-color);
  padding: 24px;
  position: sticky;
  top: 64px;
  height: calc(100vh - 64px);
  overflow-y: auto;
  transition: width 0.3s ease, padding 0.3s ease;
  flex-shrink: 0;
}

.sidebar.collapsed {
  width: 60px;
  padding: 24px 12px;
  overflow: hidden;
}

.sidebar-toggle {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 8px;
  margin-bottom: 20px;
  background: var(--bg-tertiary);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  color: var(--text-secondary);
  cursor: pointer;
  font-size: 0.8125rem;
  font-family: inherit;
  transition: all var(--transition);
}

.sidebar-toggle:hover {
  border-color: var(--border-hover);
  color: var(--text-primary);
}

.sidebar.collapsed .sidebar-toggle span,
.sidebar.collapsed .sidebar-section h4,
.sidebar.collapsed .sidebar-section a {
  display: none;
}

.sidebar.collapsed .sidebar-section {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
}

.sidebar-section {
  margin-bottom: 28px;
}

.sidebar-section h4 {
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-muted);
  margin-bottom: 12px;
}

.sidebar-section ul {
  list-style: none;
}

.sidebar-section li {
  margin-bottom: 6px;
}

.sidebar-section a {
  display: block;
  padding: 6px 10px;
  border-radius: 6px;
  font-size: 0.875rem;
  color: var(--text-secondary);
  transition: all var(--transition);
}

.sidebar-section a:hover,
.sidebar-section a.active {
  background: rgba(71, 95, 145, 0.12);
  color: var(--text-primary);
}

.main-content {
  flex: 1;
  padding: 40px 48px;
  max-width: 900px;
}

.main-content h1 {
  font-size: 2.25rem;
  margin-bottom: 16px;
}

.main-content h2 {
  font-size: 1.5rem;
  margin: 48px 0 16px;
  padding-bottom: 12px;
  border-bottom: 1px solid var(--border-color);
}

.main-content h3 {
  font-size: 1.125rem;
  margin: 32px 0 12px;
}

.main-content p {
  margin-bottom: 16px;
  line-height: 1.7;
}

.main-content ul {
  margin-bottom: 16px;
  padding-left: 20px;
}

.main-content li {
  margin-bottom: 8px;
  color: var(--text-secondary);
}

/* Grid layouts */
.grid-3 {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.grid-2 {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
}

.grid-4 {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}

/* Hero */
.hero {
  padding: 80px 0 60px;
  text-align: center;
}

.hero h1 {
  font-size: 3rem;
  margin-bottom: 20px;
  background: linear-gradient(135deg, var(--text-primary), var(--accent-light));
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.hero p {
  font-size: 1.25rem;
  max-width: 720px;
  margin: 0 auto 32px;
  color: var(--text-secondary);
}

.hero-actions {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

/* Responsive */
@media (max-width: 1024px) {
  .grid-3 { grid-template-columns: repeat(2, 1fr); }
  .grid-4 { grid-template-columns: repeat(2, 1fr); }
  .main-content { padding: 32px; }
}

@media (max-width: 768px) {
  .main-nav { display: none; }
  .mobile-menu-btn { display: block; }
  .grid-3, .grid-2, .grid-4 { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .hero h1 { font-size: 2rem; }
  .hero p { font-size: 1rem; }
  .sidebar { display: none; }
  .section { padding: 48px 0; }
}

@media (max-width: 480px) {
  .footer-grid { grid-template-columns: 1fr; }
  .footer-bottom { flex-direction: column; gap: 12px; text-align: center; }
}

/* Utility */
.text-gradient {
  background: linear-gradient(135deg, var(--accent-cyan), var(--accent-green));
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.tag {
  display: inline-block;
  padding: 4px 10px;
  border-radius: 20px;
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.tag-soon {
  background: rgba(63, 185, 80, 0.15);
  color: var(--accent-green);
  border: 1px solid rgba(63, 185, 80, 0.3);
}

/* Mobile nav overlay */
.mobile-nav {
  display: none;
  position: fixed;
  inset: 64px 0 0;
  background: var(--bg-primary);
  z-index: 99;
  padding: 24px;
  flex-direction: column;
  gap: 16px;
}

.mobile-nav.open {
  display: flex;
}

.mobile-nav a {
  font-size: 1.125rem;
  padding: 12px 0;
  border-bottom: 1px solid var(--border-color);
}

// CommerceForge Dev Docs — Global Interactions

document.addEventListener('DOMContentLoaded', () => {
  initAccordions();
  initCodeTabs();
  initSidebar();
  initMobileNav();
});

// Accordions (only one open at a time)
function initAccordions() {
  const groups = document.querySelectorAll('.accordion-group');
  groups.forEach(group => {
    const items = group.querySelectorAll('.accordion');
    items.forEach(item => {
      const header = item.querySelector('.accordion-header');
      if (!header) return;
      header.addEventListener('click', () => {
        const isOpen = item.classList.contains('open');
        items.forEach(i => i.classList.remove('open'));
        if (!isOpen) item.classList.add('open');
      });
    });
  });
}

// Code tabs
function initCodeTabs() {
  const tabGroups = document.querySelectorAll('.code-block[data-tabs]');
  tabGroups.forEach(block => {
    const tabs = block.querySelectorAll('.code-tab');
    const panes = block.querySelectorAll('.code-pane');
    tabs.forEach(tab => {
      tab.addEventListener('click', () => {
        const target = tab.dataset.tab;
        tabs.forEach(t => t.classList.remove('active'));
        panes.forEach(p => p.classList.remove('active'));
        tab.classList.add('active');
        const pane = block.querySelector(`.code-pane[data-pane="${target}"]`);
        if (pane) pane.classList.add('active');
      });
    });
  });
}

// Sidebar collapse
function initSidebar() {
  const toggles = document.querySelectorAll('.sidebar-toggle');
  toggles.forEach(btn => {
    btn.addEventListener('click', () => {
      const sidebar = btn.closest('.sidebar');
      if (sidebar) sidebar.classList.toggle('collapsed');
    });
  });
}

// Mobile nav
function initMobileNav() {
  const btn = document.querySelector('.mobile-menu-btn');
  const nav = document.querySelector('.mobile-nav');
  if (!btn || !nav) return;
  btn.addEventListener('click', () => {
    nav.classList.toggle('open');
    const icon = btn.querySelector('svg');
    if (nav.classList.contains('open')) {
      btn.innerHTML = `<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><line x1="18" y1="6" x2="6" y2="18"></line><line x1="6" y1="6" x2="18" y2="18"></line></svg>`;
    } else {
      btn.innerHTML = `<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><line x1="3" y1="12" x2="21" y2="12"></line><line x1="3" y1="6" x2="21" y2="6"></line><line x1="3" y1="18" x2="21" y2="18"></line></svg>`;
    }
  });
}

